func main() {
    m := map[int]uint32{
       1: 100,
       2: 200,
    }
    v := reflect.ValueOf(m)
    for _, k := range v.MapKeys() {
       field := v.MapIndex(k)
       fmt.Printf("key type is %v, key = %d; value type is %v, value = %d\n", k.Type().Name(), k.Int(), field.Type().Name(), field.Uint())
    }
}

