       fmt.Printf("field1 name is %s, field1 type is %s\n", t.Elem().Field(i).Name, t.Elem().Field(i).Type.String())
    }

}

package main

import (
    "fmt"
    "reflect"
)

func Add(num1, num2 int) (int, error) {
    return num1 + num2, nil
}

func main() {

    fmt.Println("input:")
    t := reflect.TypeOf(Add)
    for i := 0; i < t.NumIn(); i++ {
       tIn := t.In(i)
       fmt.Print(tIn.Name())
       fmt.Printf(" ")
    }
    fmt.Printf("\n--------------------------------")

    fmt.Println("output:")
    for i := 0; i < t.NumOut(); i++ {
       tOut := t.Out(i)
       fmt.Print(tOut.Name())
       fmt.Print(" ")
    }

}

